/**
 * Pi 모델 카탈로그 — 서버가 Pi 설정에서 읽어 내려주는 목록(`GET /api/pi/models`).
 *
 * 화면이 목록을 따로 들고 있지 않은 이유는 하나다: Pi에 로그인한 provider와 모델이 바뀌면
 * 컴포저의 선택지도 같이 바뀌어야 한다. 서버는 `~/.pi/agent/auth.json`(로그인 상태)과
 * `models-store.json`(모델·thinking level)을 그때그때 읽고, 여기서는 그 응답만 다룬다.
 * effort 규칙도 Pi의 것을 그대로 쓴다(`getSupportedThinkingLevels`, `clampThinkingLevel`).
 */
import { request } from "$lib/api/request.js";

/** Pi의 level 순서. 마지막이 가장 높은 effort다. */
export const piEffortLevels = ["off", "minimal", "low", "medium", "high", "xhigh", "max"] as const;
export type PiEffort = (typeof piEffortLevels)[number];

export type PiModel = {
	/** Pi가 받는 참조: `provider/modelId`. */
	id: string;
	name: string;
	provider: string;
	/** 그 모델이 허용하는 level만, Pi 순서대로. */
	efforts: PiEffort[];
};

export type PiProvider = {
	id: string;
	label: string;
	models: PiModel[];
};

/** 팝오버 목록 한 줄. 목록은 `provider/modelId`를 그대로 보여 주고 provider로 묶는다. */
export type PiPickerItem = { value: string; group?: string };

/** Settings › Models 의 Model list 섹션: pi 카탈로그 전체와 `model-filter.json` 의 상태.
 *  `version` 은 저장할 때 그대로 돌려보내고, 그 사이 파일이 바뀌었으면 서버가 409로 거절한다. */
export type PiFilterModel = { id: string; name: string; free: boolean; listed: boolean; missing: boolean };
export type PiFilterProvider = { id: string; label: string; restricted: boolean; models: PiFilterModel[] };
export type PiFilterView = {
	enabled: boolean;
	includeFree: boolean;
	version: string;
	problem: string | null;
	providers: PiFilterProvider[];
};

export async function fetchPiFilter(signal?: AbortSignal): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter", { signal });
}

/** `enabled` 와 `providers` 는 pi 파일에 쓰고, 빠진 provider 는 제한이 풀린다. */
export function savePiFilter(next: {
	enabled: boolean;
	providers: Record<string, string[]>;
	version: string;
}): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter", {
		method: "PUT",
		body: JSON.stringify(next),
	});
}

/** 대시보드만의 free 포함 여부(`~/.local/state/dashboard/model-filter.json`). */
export function saveFreeModels(includeFree: boolean): Promise<PiFilterView> {
	return request<PiFilterView>("/api/pi/model-filter/free", {
		method: "PUT",
		body: JSON.stringify({ includeFree }),
	});
}

/** `/api/pi/models`: 필터가 남긴 목록과, 필터가 가렸을 뿐 아직 돌릴 수 있는 모델 id.
 *  저장된 선택이 `hidden` 에 있으면 대안으로 바꾸지 않는다(필터는 보이는 목록만 줄인다). */
export type PiCatalog = { providers: PiProvider[]; hidden: string[] };

export async function fetchPiCatalog(signal?: AbortSignal): Promise<PiCatalog> {
	const body = await request<{ providers?: PiProvider[]; hidden?: string[] }>("/api/pi/models", {
		signal,
	});
	return {
		providers: Array.isArray(body.providers) ? body.providers : [],
		hidden: Array.isArray(body.hidden) ? body.hidden : [],
	};
}

export async function fetchPiModels(signal?: AbortSignal): Promise<PiProvider[]> {
	return (await fetchPiCatalog(signal)).providers;
}

/** provider 순서대로 한 줄씩, provider 머리글을 달아서. */
export function piPickerItems(providers: PiProvider[]): PiPickerItem[] {
	return providers.flatMap((provider) =>
		provider.models.map((model) => ({
			value: model.id,
			group: provider.label,
		})),
	);
}

/** 지금 값이 필터로 빠졌어도 목록에는 남긴다(pi 선택기의 "지금 쓰는 모델은 목록에 없어도 남는다").
 *  같은 provider 의 마지막 항목 뒤에 넣어 머리글이 두 번 서지 않게 하고, provider 자체가 사라졌으면
 *  이름을 알 수 없으니 묶음 없이 끝에 둔다. */
export function withCurrentModel(
	items: PiPickerItem[],
	providers: PiProvider[],
	current: string | undefined,
): PiPickerItem[] {
	if (!current || items.some((item) => item.value === current)) return items;
	const slash = current.indexOf("/");
	const provider = slash > 0 ? current.slice(0, slash) : "";
	const group = providers.find((entry) => entry.id === provider)?.label;
	let at = -1;
	if (group) {
		for (let i = items.length - 1; i >= 0; i -= 1) {
			if (items[i]?.group === group) {
				at = i;
				break;
			}
		}
	}
	const entry: PiPickerItem = { value: current, group };
	if (at < 0) return [...items, entry];
	return [...items.slice(0, at + 1), entry, ...items.slice(at + 1)];
}

/**
 * 그 모델이 허용하는 level. 카탈로그에서 사라진 id는 비워 두지 않는다: 빈 목록은 열리지 않는
 * 드롭다운이 되기 때문이다(등급 화면의 premium 줄에서 실제로 그랬다). provider가 바뀐 같은 모델을
 * 이름으로 다시 찾고, 그것도 없으면 Pi의 level 전체를 연다. 값은 그대로 남는다.
 */
export function piEffortsFor(providers: PiProvider[], id: string): PiEffort[] {
	const models = providers.flatMap((provider) => provider.models);
	const exact = models.find((model) => model.id === id);
	if (exact) return exact.efforts;
	const bare = id.slice(id.lastIndexOf("/") + 1);
	const moved = models.find((model) => model.id === bare || model.id.endsWith(`/${bare}`));
	return moved?.efforts ?? [...piEffortLevels];
}

/**
 * Pi의 `clampThinkingLevel`과 같은 규칙: 그 level이 없으면 지원 목록에서 가장 가까운 위쪽,
 * 그다음 아래쪽으로 내린다. 카탈로그가 비어 있으면(로그인된 모델 없음) 지금 값을 그대로 둔다.
 */
export function clampPiEffort(efforts: PiEffort[], effort: string): PiEffort {
	if (efforts.includes(effort as PiEffort)) return effort as PiEffort;
	const at = piEffortLevels.indexOf(effort as PiEffort);
	if (at < 0) return efforts[0] ?? "off";
	for (let i = at; i < piEffortLevels.length; i++) {
		if (efforts.includes(piEffortLevels[i])) return piEffortLevels[i];
	}
	for (let i = at - 1; i >= 0; i--) {
		if (efforts.includes(piEffortLevels[i])) return piEffortLevels[i];
	}
	return efforts[0] ?? "off";
}

/**
 * 고른 모델이 카탈로그에 남아 있으면 그대로, 필터가 가렸으면 그대로(아직 돌릴 수 있으니),
 * 정말 사라졌으면 대안, 그것도 없으면 첫 모델. 카탈로그를 못 읽었을 때는 지금 값을 유지한다
 * (빈 이름이 버튼에 남지 않게).
 */
export function resolvePiModel(
	providers: PiProvider[],
	current: string,
	fallback: string,
	hidden: string[] = [],
): string {
	const all = providers.flatMap((provider) => provider.models.map((model) => model.id));
	if (all.length === 0) return current;
	if (all.includes(current) || hidden.includes(current)) return current;
	if (all.includes(fallback)) return fallback;
	return all[0] ?? current;
}

