export function piEffortsFor(providers: PiProvider[], id: string): PiEffort[] {
	const models = providers.flatMap((provider) => provider.models);
	const exact = models.find((model) => model.id === id);
	if (exact) return exact.efforts;
	const bare = id.slice(id.lastIndexOf("/") + 1);
	const moved = models.find((model) => model.id === bare || model.id.endsWith(`/${bare}`));
	return moved?.efforts ?? [...piEffortLevels];
}

edits.newText:
/** 그 id의 모델이 허용하는 level. provider가 바뀐 같은 모델은 이름으로 다시 찾고, 없으면 undefined. */
function catalogEfforts(providers: PiProvider[], id: string): PiEffort[] | undefined {
	const models = providers.flatMap((provider) => provider.models);
	const exact = models.find((model) => model.id === id);
	if (exact) return exact.efforts;
	const bare = id.slice(id.lastIndexOf("/") + 1);
	return models.find((model) => model.id === bare || model.id.endsWith(`/${bare}`))?.efforts;
}

export function piEffortsFor(providers: PiProvider[], id: string): PiEffort[] {
	return catalogEfforts(providers, id) ?? [...piEffortLevels];
}

/**
 * 그 모델의 level 가운데 받는 쪽(`within`)이 아는 것만, Pi 순서로.
 * cc-proxy는 `output_config.effort`로 low–max만 보내므로 그 사다리와 겹치는 것만 연다.
 * 카탈로그에서 사라진 모델이거나 겹치는 level이 없으면 받는 쪽 목록 전체를 연다
 * (빈 목록은 열리지 않는 드롭다운이 되기 때문이다).
 */
export function piEffortsWithin(providers: PiProvider[], id: string, within: readonly PiEffort[]): PiEffort[] {
	const known = catalogEfforts(providers, id);
	if (!known) return [...within];
	const allowed = new Set<string>(within);
	const kept = piEffortLevels.filter((level) => known.includes(level) && allowed.has(level));
	return kept.length > 0 ? kept : [...within];
}

